import { ArrowRight, BarChart3, Boxes, CreditCard, Package, Receipt, Truck } from 'lucide-react'
import { useEffect, useState, type ReactNode } from 'react'
import { reportApi, type Vendor } from '../../api'
import { AdminPageHeader, StatCard } from '../../components/admin/AdminShell'
import { Card, CardContent, CardHeader } from '../../components/ui/card'

export function VendorOverviewPage({ vendor, storeId, onViewChange }: { vendor?: Vendor; storeId?: number; onViewChange: (view: 'pos' | 'inventory' | 'catalog' | 'debt' | 'deliveries' | 'reports') => void }) {
  const [sales, setSales] = useState<{ saleCount: number; subtotal: number; discount: number; vat: number; total: number } | null>(null)
  useEffect(() => { if (vendor && storeId) reportApi.sales(vendor.id, storeId).then(setSales).catch(() => setSales(null)) }, [vendor, storeId])
  return <><AdminPageHeader eyebrow="Store operations" title={vendor ? `${vendor.name} overview` : 'Store overview'} description="A focused workspace for selling, stock, products, customer credit, and daily store operations." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Sales today" value={sales ? `PHP ${sales.total.toLocaleString()}` : '—'} detail={sales ? `${sales.saleCount} completed sales` : 'Select a store for totals'} icon={Receipt} tone="emerald" /><StatCard label="Inventory" value="—" detail="Open inventory to inspect stock" icon={Boxes} /><StatCard label="Catalog" value="—" detail="Products and categories" icon={Package} tone="indigo" /><StatCard label="Credit balance" value="—" detail="Debt account summary" icon={CreditCard} tone="amber" /></div><div className="mt-6 grid gap-6 lg:grid-cols-2"><Card><CardHeader><h2 className="font-bold">Quick actions</h2><p className="mt-1 text-sm text-slate-500">Jump into the work that happens most often.</p></CardHeader><CardContent className="grid gap-2 sm:grid-cols-2"><QuickAction icon={<Receipt />} label="Open POS" text="Start a sale" onClick={() => onViewChange('pos')} /><QuickAction icon={<Boxes />} label="Receive stock" text="Update inventory" onClick={() => onViewChange('inventory')} /><QuickAction icon={<Package />} label="Manage catalog" text="Products and categories" onClick={() => onViewChange('catalog')} /><QuickAction icon={<Truck />} label="Review deliveries" text="Upcoming receiving" onClick={() => onViewChange('deliveries')} /></CardContent></Card><Card><CardHeader><h2 className="font-bold">Workflow</h2><p className="mt-1 text-sm text-slate-500">Keep the store process clear.</p></CardHeader><CardContent className="space-y-3 text-sm text-slate-600"><p className="flex gap-3"><span className="grid size-6 place-items-center rounded-full bg-indigo-50 text-xs font-bold text-indigo-600">1</span> Search or scan a product in POS.</p><p className="flex gap-3"><span className="grid size-6 place-items-center rounded-full bg-indigo-50 text-xs font-bold text-indigo-600">2</span> Complete payment and issue a receipt.</p><p className="flex gap-3"><span className="grid size-6 place-items-center rounded-full bg-indigo-50 text-xs font-bold text-indigo-600">3</span> Inventory is deducted from the selected store.</p><button onClick={() => onViewChange('reports')} className="mt-2 inline-flex items-center gap-1 font-bold text-indigo-600">View reports <ArrowRight size={15} /></button></CardContent></Card></div></>
}

function QuickAction({ icon, label, text, onClick }: { icon: ReactNode; label: string; text: string; onClick: () => void }) { return <button onClick={onClick} className="flex items-center gap-3 rounded-xl bg-slate-50 p-3 text-left hover:bg-indigo-50"><span className="grid size-9 place-items-center rounded-lg bg-white text-indigo-600 shadow-sm">{icon}</span><span><strong className="block text-sm">{label}</strong><small className="text-xs text-slate-500">{text}</small></span></button> }
